require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}function is_process_alive($pid){if(!function_exists('posix_kill')||!@posix_kill((int)$pid,0)){return false;}return true;}require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/PanSou.php';require_once __DIR__.'/../core/StaticGen.php';$ids=array();$delay=60;$fromPending=false;foreach(array_slice($argv,1)as $arg){if(strpos($arg,'--ids=')===0){$raw=substr($arg,6);foreach(explode(',',$raw)as $x){$x=(int)trim($x);if($x>0){$ids[]=$x;}}}elseif(strpos($arg,'--delay=')===0){$delay=max(0,min(300,(int)substr($arg,8)));}elseif($arg==='--from-pending'){$fromPending=true;}}$pendingFile=__DIR__.'/../config/pan_pending.txt';$pendingIds=array();if($fromPending){if(is_file($pendingFile)){$fh=@fopen($pendingFile,'r+');if($fh){if(@flock($fh,LOCK_EX)){$raw='';while(($b=@fread($fh,8192))!==false){$raw.=$b;}@ftruncate($fh,0);@fseek($fh,0);@fflush($fh);@flock($fh,LOCK_UN);@fclose($fh);foreach(explode(',',$raw)as $x){$x=(int)trim($x);if($x>0){$pendingIds[]=$x;}}}else{@fclose($fh);}}}$pendingIds=array_values(array_unique($pendingIds));foreach($pendingIds as $x){if(!in_array($x,$ids,true)){$ids[]=$x;}}if(empty($ids)){fwrite(STDOUT,"[pan_match_delayed] 待处理队列为空，无事可做。\n");exit(0);}$delay=min($delay,5);}if(empty($ids)){fwrite(STDERR,"用法：php cron/pan_match_delayed.php --ids=123,456 [--delay=60]\n");fwrite(STDERR,"  --ids           逗号分隔的 media_items.id 列表\n");fwrite(STDERR,"  --delay         等待秒数（默认 60，最大 300）\n");fwrite(STDERR,"  --from-pending  消费 config/pan_pending.txt 待处理队列（exec 被禁用时由计划任务定期跑）\n");exit(1);}$lockFile=__DIR__.'/../config/pan_match.lock';$lockPid=getmypid();if(file_exists($lockFile)){$oldPid=(int)file_get_contents($lockFile);if($oldPid>0&&is_process_alive($oldPid)){fwrite(STDERR,'已有网盘匹配任务在运行（PID='.$oldPid.'），本次跳过。'."\n");exit(0);}}file_put_contents($lockFile,(string)$lockPid);$t0=microtime(true);fwrite(STDOUT,"[pan_match_delayed] 启动，ID 数=".count($ids)."，等待 $delay 秒...\n");fwrite(STDOUT,"  时间：".date('Y-m-d H:i:s')."\n");sleep($delay);function requeuePending(array $ids){global $pendingFile;if(empty($ids)||$pendingFile===''){return;}$fh=@fopen($pendingFile,'c+');if(!$fh){return;}try{if(!@flock($fh,LOCK_EX)){return;}@fseek($fh,0);$cur='';while(($b=@fread($fh,8192))!==false){$cur.=$b;}$existing=array();foreach(explode(',',$cur)as $x){$x=(int)trim($x);if($x>0){$existing[$x]=true;}}foreach($ids as $x){$x=(int)$x;if($x>0&&!isset($existing[$x])){$existing[$x]=true;}}$list=array_keys($existing);if(count($list)>1000){$list=array_slice($list,-1000);}@ftruncate($fh,0);@fseek($fh,0);@fwrite($fh,implode(',',$list));@fflush($fh);}finally{@flock($fh,LOCK_UN);@fclose($fh);}}fwrite(STDOUT,"[pan_match_delayed] 开始匹配（本地优先，PanSou 兜底）...\n");try{$rep=\Core\PanSou::enrichLocalFirst($ids,max(1,count($ids)));$ms=(int)round((microtime(true)-$t0)*1000);fwrite(STDOUT,"[pan_match_delayed] 完成：\n");fwrite(STDOUT,"  检查={$rep['checked']} 本地复用={$rep['local_matched']} PanSou匹配={$rep['pansou_matched']} 无匹配={$rep['nomatch']} 写入={$rep['written']} 链接={$rep['links']} 错误=".count($rep['errors'])." 耗时={$ms}ms\n");if(!empty($rep['errors'])){fwrite(STDERR,"  错误详情：\n");foreach($rep['errors']as $err){fwrite(STDERR,"    - $err\n");}}foreach($rep['items']as $item){if(strpos($item['action'],'写入')!==false||strpos($item['action'],'复用')!==false){try{\Core\StaticGen::buildOne((int)$item['id']);}catch(\Throwable $e){}}}if($fromPending){$requeue=array();foreach($rep['items']as $item){$act=isset($item['action'])?(string)$item['action']:'';if(strpos($act,'写入')!==false||strpos($act,'复用')!==false){continue;}$iid=(int)(isset($item['id'])?$item['id']:0);if($iid>0){$requeue[]=$iid;}}if($requeue){requeuePending(array_values(array_unique($requeue)));fwrite(STDOUT,"  已将 ".count($requeue)." 个未匹配 ID 回队（下次 --from-pending 再试）\n");}}}catch(\Throwable $e){fwrite(STDERR,"[pan_match_delayed] 异常：".$e->getMessage()."\n");if($fromPending){requeuePending($pendingIds);}exit(1);}@unlink($lockFile);exit(0);